from datetime import datetime

from taf.internal.robot_typecasts import time_to_seconds
from taf.rfrl.procedures.resources.python.logger import log_input_and_output, log_operation, log_result

from taf.rfrl.procedures.resources.python.exceptions import TimeoutError


class TimeMeasurement:
    def __init__(self):
        self.data = datetime
        self.start_time = None
        self.stop_time = None

    @log_input_and_output
    def start_measurement_time(self):
        """
        Start measurement time
        """
        self.start_time = self.data.now()
        log_operation("Start time of execution: {}".format(self.start_time))

    @log_input_and_output
    def stop_measurement_time(self, timeout=None, fail=True):
        """
        Stop measurement time

        :param timeout: expected maximum measurement time - if exceeded TimeoutError is raised;
                        accepts Robot string time format i.e. 1 min 30 sec
        :type timeout: int, float or str
        :param fail: If True then raise TimeoutError when time of execution exceeded provided timeout
                     Otherwise return True
        :type fail: bool
        :raise TimeoutError: When time of execution exceeded provided timeout
        :return bool or in: If fail is False then return True else time of execution.
        """
        self.stop_time = self.data.now()
        if not timeout:
            return self.stop_time - self.start_time

        log_result("Maximum allowed time of execution: {}\n"
                   "Stop time of execution: {}".format(timeout, self.stop_time))

        return self._check_execution_time(time_to_seconds(timeout), fail)

    @log_input_and_output
    def _check_execution_time(self, timeout, fail):
        execution_time = self.stop_time - self.start_time
        execution_time_msg = "Execution time: {}".format(execution_time)
        log_result(execution_time_msg)

        if round(execution_time.total_seconds(), ndigits=2) > timeout:
            if fail:
                raise TimeoutError(execution_time_msg)
            else:
                return True
        else:
            return execution_time.total_seconds()
